head.script:
// 담당 범위 : min 가이드 전 항목 (con_min 1개, 검증 Column 3개를 한 화면에서 비교)
//  - "Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외 (column 샘플 관례, 설정 영역 con 옵션 미생성, Body Column 에만 설정)
//  - validation 6 의 "increment 속성값과 관계없이" 확인을 위해 3개 Column 모두 increment="3" 고정 (가이드 문구에 명시된 범위만 전제로 사용)
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > min]<br/>inputType='spinner' 인 Column 에 입력할 수 있는 최소값을 설정합니다.",
    "validation" : [
        "Column 의 dataType 속성을 설정하지 않았거나 dataType='number' 인 경우에 동작합니다.",
        "숫자 설정 시, Cell 에 입력할 수 있는 최소값을 숫자로 설정합니다.",
        "숫자 설정 시, 증감 버튼이나 화살표키로 Cell 값을 감소시키면 설정한 값보다 작아지지 않습니다.",
        "숫자 설정 시, 설정한 값보다 작은 값을 직접 입력하면 입력을 마칠 때 설정한 값으로 변경됩니다.",
        "입력하거나 증감 버튼으로 변경한 값에만 적용되며, 메소드로 설정하거나 초기값에는 적용되지 않습니다.",
        "Cell 값이 비어 있는 상태에서 증감 버튼이나 화살표키로 증감하면 increment 속성값과 관계없이 min 속성값이 입력됩니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (10)
    con_min.setValue("10");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - numNone : spinner, dataType 미설정    (validation 1 : 동작)
//  - num     : spinner, dataType=number    (validation 1 : 동작)
//  - date    : spinner, dataType=date      (validation 1 : 미동작 대조)
//  - 3개 Column 모두 min = con_min (미설정은 속성 자체를 넣지 않는다), increment = 3 고정
//  - Row 0 = 12, Row 1 = 5 (min 10 / 10.5 / 50 에서 최소값보다 작은 초기값 : validation 5), Row 2 = 빈 값 (validation 6)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 3개 Column 모두 같은 min 설정, increment 는 3 고정, 초기값은 Row 0 = 12, Row 1 = 5, Row 2 = 빈 값\n[절차] Cell 더블클릭으로 편집 진입 -> 감소(또는 증가) 버튼 클릭, 또는 입력창 클릭 후 아래(또는 위) 화살표키, 또는 입력창 클릭 후 값을 지우고 -9999 입력 -> 결과창 클릭으로 편집 종료\n[확인] 편집 종료마다 변경 전 -> 변경 후 값 자동 출력 (값이 바뀌지 않으면 출력 없음), 생성 시 초기값 출력, setCellData 버튼으로 메소드 설정값 확인"', '', 'label1');

    // 조건 설정 (자체 값 select -> getValue, 미설정은 속성 자체를 넣지 않는다)
    let cMin = con_min.getValue();
    let attrMin = (cMin === '') ? '' : ' min="' + cMin + '"';

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 dataList (body column id 와 동일한 컬럼 id 사용)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="numNone" name="numNone" dataType="number"></w2:column>';
    strDlt += '<w2:column id="num" name="num" dataType="number"></w2:column>';
    strDlt += '<w2:column id="date" name="date" dataType="date"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "numNone" : "12", "num" : "12", "date" : "20261001" },
        { "numNone" : "5", "num" : "5", "date" : "20261231" },
        { "numNone" : "", "num" : "", "date" : "" }
    ], false);

    // 이벤트 바인딩 (편집 종료 시 값 변경 출력)
    let eList = $c.gcm.createEList(["onviewchange"]);

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + eList + ' dataList="data:dlt_bind" checkAllType="false" defaultCellHeight="30" id="" style="width:600px;height:150px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="column1" value="numNone (dataType 미설정)"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="text" id="column2" value="num (dataType=number)"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="text" id="column3" value="date (dataType=date)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="200" style="" inputType="spinner" id="numNone" value="" increment="3"' + attrMin + '></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="spinner" dataType="number" id="num" value="" increment="3"' + attrMin + '></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="spinner" dataType="date" id="date" value="" increment="3"' + attrMin + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // validation 5 판정 출력 : 최소값보다 작은 초기값이 그대로 유지되는지 (DataList 값 / 셀 표시값)
    wf_body_bottom.getObj("scwin").setReturnValue("초기값 Row 1 : numNone '" + dlt_bind.getCellData(1, "numNone") + "' (표시 " + target1.getCellDisplayData(1, "numNone") + ") / num '" + dlt_bind.getCellData(1, "num") + "' (표시 " + target1.getCellDisplayData(1, "num") + ")");
}



// validation 1 ~ 4, 6 판정 출력 : 편집 종료 시 변경 전 -> 변경 후 값
scwin.target1_onviewchange = function (info) {
    let colId = target1.getColumnID(info.colIndex);
    let oldValue = (info.oldValue === undefined || info.oldValue === null) ? "" : String(info.oldValue);
    let newValue = (info.newValue === undefined || info.newValue === null) ? "" : String(info.newValue);
    wf_body_bottom.getObj("scwin").setReturnValue("Row " + info.rowIndex + " / " + colId + " : '" + oldValue + "' -> '" + newValue + "'");
}



// validation 5 판정 출력 : 메소드로 최소값보다 작은 값을 설정하면 그대로 저장되는지 (바인딩 DataList 의 setCellData)
scwin.btn_setCellData_onclick = function (e) {
    dlt_bind.setCellData(0, "numNone", "-9999");
    dlt_bind.setCellData(0, "num", "-9999");
    wf_body_bottom.getObj("scwin").setReturnValue("setCellData(Row 0, -9999) -> numNone '" + dlt_bind.getCellData(0, "numNone") + "' (표시 " + target1.getCellDisplayData(0, "numNone") + ") / num '" + dlt_bind.getCellData(0, "num") + "' (표시 " + target1.getCellDisplayData(0, "num") + ")");
};
